solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct {
    char **words;
    size_t count, width;
    bool leading[26], used[10];
    int *map;
} puzzle;
static bool column(puzzle *p, size_t col, size_t word, int sum) {
    if (col == p->width)
        return sum == 0;
    if (word + 1 == p->count) {
        char *s = p->words[word];
        size_t n = strlen(s);
        if (col >= n)
            return sum == 0 && column(p, col + 1, 0, 0);
        int l = s[n - col - 1] - 'A', d = sum % 10;
        if (p->map[l] >= 0)
            return p->map[l] == d && column(p, col + 1, 0, sum / 10);
        if (p->used[d] || (d == 0 && p->leading[l]))
            return false;
        p->map[l] = d;
        p->used[d] = true;
        if (column(p, col + 1, 0, sum / 10))
            return true;
        p->used[d] = false;
        p->map[l] = -1;
        return false;
    }
    char *s = p->words[word];
    size_t n = strlen(s);
    if (col >= n)
        return column(p, col, word + 1, sum);
    int l = s[n - col - 1] - 'A';
    if (p->map[l] >= 0)
        return column(p, col, word + 1, sum + p->map[l]);
    for (int d = 0; d < 10; d++)
        if (!p->used[d] && (d || !p->leading[l])) {
            p->map[l] = d;
            p->used[d] = true;
            if (column(p, col, word + 1, sum + d))
                return true;
            p->map[l] = -1;
            p->used[d] = false;
        }
    return false;
}
bool solve(const char *t, int map[26]) {
    puzzle p = {NULL, 0, 0, {false}, {false}, map};
    for (int i = 0; i < 26; i++)
        map[i] = -1;
    bool letters[26] = {false};
    size_t distinct = 0;
    while (*t) {
        if (*t < 'A' || *t > 'Z') {
            t++;
            continue;
        }
        const char *start = t;
        while (*t >= 'A' && *t <= 'Z') {
            int l = *t - 'A';
            if (!letters[l]) {
                letters[l] = true;
                distinct++;
            }
            t++;
        }
        size_t n = (size_t)(t - start);
        char *w = (char *)malloc(n + 1);
        memcpy(w, start, n);
        w[n] = 0;
        p.words = (char **)realloc(p.words, (p.count + 1) * sizeof(char *));
        p.words[p.count++] = w;
        if (n > 1)
            p.leading[w[0] - 'A'] = true;
        if (n > p.width)
            p.width = n;
    }
    bool ok = p.count >= 2 && distinct <= 10 && column(&p, 0, 0, 0);
    for (size_t i = 0; i < p.count; i++)
        free(p.words[i]);
    free(p.words);
    return ok;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    int m[26];
    assert(solve("SEND + MORE == MONEY", m));
    assert(m['S' - 'A'] == 9 && m['E' - 'A'] == 5 && m['N' - 'A'] == 6 &&
           m['D' - 'A'] == 7 && m['M' - 'A'] == 1 && m['O' - 'A'] == 0 &&
           m['R' - 'A'] == 8 && m['Y' - 'A'] == 2);
    assert(!solve("A == B", m));
    assert(solve("I + BB == ILL", m) && m['I' - 'A'] == 1 && m['B' - 'A'] == 9);

    return 0;
}
